    private void rig(FourChessView b){try{int[][] hands=(int[][])field(b,"skillHands");int[][] charges=(int[][])field(b,"skillCharges");int[] used=(int[])field(b,"skillUse");java.util.Arrays.fill(used,0);for(int o=0;o<4;o++){java.util.Arrays.fill(charges[o],0);for(int i=0;i<4;i++){hands[o][i]=i+1;charges[o][i+1]=1;}}}catch(Exception e){throw new RuntimeException(e);}}
    private String legacy(String state){if(!state.contains(",K1"))return state;String[] parts=state.split("\\|",2);StringBuilder header=new StringBuilder(parts[0].replace(",K1",",K4"));for(int o=0;o<4;o++)for(int id=1;id<=4;id++)header.append(',').append(id);for(int i=0;i<16;i++)header.append(",1");header.append(",0,0,12345");return header+"|"+parts[1];}
    private Bundle args;private MainActivity activity;private FourChessView board;private ModeSelectView mode;
    private final StringBuilder report=new StringBuilder();private final List<NetworkManager> resources=new ArrayList<>();
    @Override public void onCreate(Bundle value){super.onCreate(value);args=value;start();}
    private void check(boolean ok,String description){if(!ok)throw new AssertionError(description);report.append("PASS ").append(description).append('\n');}
    private Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});waitForIdleSync();if(error.get()!=null)throw new AssertionError(error.get());}
    private interface Condition {boolean get()throws Exception;}
    private void await(Condition c,String description)throws Exception{for(int i=0;i<140;i++){if(c.get()){check(true,description);return;}SystemClock.sleep(50);}throw new AssertionError(description);}
    private void call(String name)throws Exception{Method method=MainActivity.class.getDeclaredMethod(name);method.setAccessible(true);method.invoke(activity);}
    private void tap(View v,float x,float y){main(()->{long now=SystemClock.uptimeMillis();for(int a:new int[]{0,1}){MotionEvent e=MotionEvent.obtain(now,now,a,x,y,0);v.dispatchTouchEvent(e);e.recycle();}});SystemClock.sleep(300);}
    private void tapSquare(int x,int y)throws Exception{tap(board,(Float)field(board,"ox")+x*(Float)field(board,"cellX"),(Float)field(board,"oy")+y*(Float)field(board,"cellY"));}
    private int[] square(FourChessView b,int owner,int file,int depth)throws Exception{Method m=FourChessView.class.getDeclaredMethod("toBoard",int.class,int.class,int.class);m.setAccessible(true);return (int[])m.invoke(b,owner,file,depth);}
    @SuppressWarnings("unchecked") private List<FourChessView.Piece> pieces(FourChessView b)throws Exception{return (List<FourChessView.Piece>)field(b,"pieces");}
    private FourChessView.Piece at(FourChessView b,int x,int y)throws Exception{for(FourChessView.Piece p:pieces(b))if(p.x==x&&p.y==y)return p;return null;}
    private String turn(String state,int value){return value+state.substring(state.indexOf(','));}
    private String removePawn(String state,int owner,int x,int y){return state.replace(owner+",B,"+x+","+y+",0;","");}
    private void shot(String name)throws Exception{SystemClock.sleep(100);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
